package gen

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/samber/lo"

	"github.com/vasilesk/allgen/internal/source"
)

var (
	// ErrForeignFile means an output file exists and was not generated by allgen.
	ErrForeignFile = errors.New("output file was not generated by allgen")
	// ErrOutputTaken means an output file was generated for another block whose directive
	// is still present in the package.
	ErrOutputTaken = errors.New("output file belongs to another block")
)

// owner identifies the block a file was generated for.
type owner struct {
	source    string
	directive string
}

// alive reports whether the directive of o is still present in its source file in dir.
func (o owner) alive(dir string) bool {
	file, err := source.Parse(filepath.Join(dir, o.source))
	if err != nil {
		return false
	}

	_, err = file.DirectiveLine(o.directive)

	return err == nil
}

// writeFiles writes files to dir once every one of them is checked to be safe to replace.
func writeFiles(dir string, files []output, self owner) error {
	for _, f := range files {
		err := checkOverwrite(dir, f.name, self)
		if err != nil {
			return err
		}
	}

	for _, f := range files {
		err := writeFile(dir, f)
		if err != nil {
			return err
		}
	}

	return nil
}

func writeFile(dir string, f output) error {
	//nolint:gosec // generated sources are as readable as the rest of the package
	err := os.WriteFile(filepath.Join(dir, f.name), f.content, 0o644)
	if err != nil {
		return fmt.Errorf("writing %s: %w", f.name, err)
	}

	return nil
}

// checkOverwrite allows replacing name in dir when it does not exist, was generated for
// self, or was generated for a block whose directive is gone.
func checkOverwrite(dir, name string, self owner) error {
	content, err := os.ReadFile(filepath.Join(dir, name))
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}

	if err != nil {
		return fmt.Errorf("reading %s: %w", name, err)
	}

	prev, ok := parseOwner(content)

	switch {
	case !ok:
		return fmt.Errorf("%w: %s", ErrForeignFile, name)
	case prev == self || !prev.alive(dir):
		return nil
	default:
		return fmt.Errorf("%w: %s was generated for %q in %s; set another function name or output file",
			ErrOutputTaken, name, prev.directive, prev.source)
	}
}

// hideGenerated returns an overlay replacing every non-test file generated by allgen in
// dir with an empty file of package pkgName.
func hideGenerated(dir, pkgName string) (map[string][]byte, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("listing package directory: %w", err)
	}

	paths := lo.FilterMap(entries, func(e os.DirEntry, _ int) (string, bool) {
		name := e.Name()

		return filepath.Join(dir, name), e.Type().IsRegular() &&
			strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go")
	})

	overlay := map[string][]byte{}

	for _, path := range paths {
		generated, err := isGenerated(path)
		if err != nil {
			return nil, err
		}

		if generated {
			overlay[path] = []byte("package " + pkgName + "\n")
		}
	}

	return overlay, nil
}

func isGenerated(path string) (bool, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return false, fmt.Errorf("reading %s: %w", filepath.Base(path), err)
	}

	_, ok := parseOwner(content)

	return ok, nil
}

// parseOwner reads the block a file was generated for from its header.
func parseOwner(content []byte) (owner, bool) {
	const headerLines = 3

	lines := strings.SplitN(string(content), "\n", headerLines+1)
	if len(lines) <= headerLines {
		lines = make([]string, headerLines)
	}

	src, okSource := strings.CutPrefix(lines[1], sourcePrefix)
	directive, okDirective := strings.CutPrefix(lines[2], directivePrefix)

	return owner{source: src, directive: directive}, lines[0] == generatedLine && okSource && okDirective
}
